import json
from pathlib import Path
extra={
'02-001':'Для проверки политической организации полезно отдельно проследить сбор ресурсов, дипломатические действия и управление населением вне главного центра. Скандинавское имя участника договора показывает присутствие человека в определённом окружении, но не определяет происхождение всех подданных. Точно так же местное земледелие объясняет хозяйственную основу, но само по себе не доказывает наличие единой власти. Сильное объяснение связывает эти свидетельства механизмом: как доход от торговли и дани поддерживал вооружённую группу, какие соглашения позволяли ей действовать и насколько устойчивыми были её отношения с общинами. Это несколько вопросов, а не спор о единственном «создателе государства».',
'02-002':'При сопоставлении летописных списков обращают внимание не только на общую дату, но и на различия имён, мест и последовательности событий. Совпадение рассказа в поздних копиях может отражать общий письменный источник. Археология Ладоги и других северных центров помогает установить присутствие торговцев и военных групп, однако не является личным удостоверением Рюрика. Различайте вывод о международной среде региона и вывод о конкретной биографии. Условная дата начала династии сохраняет учебную пользу, если прямо назвать её основание и не заполнять пробелы уверенными подробностями, которых источники не дают.',
'02-003':'При работе с договором важно выяснить, какие группы названы участниками, какие нарушения предполагаются и кто обеспечивает исполнение. Юридическое регулирование торговли показывает устойчивость контактов, но не сообщает объёма товарооборота. Рассказ об объединении Киева и северных центров объясняет политическое первенство князя; реальный контроль над путями мог складываться постепенно. Поэтому внешняя дипломатическая активность и внутренняя территориальная организация требуют разных доказательств. В учебном сравнении полезно взять одно положение договора и спросить, какие практические отношения оно предполагает, а затем отметить, каких количественных выводов из него сделать нельзя.',
'02-004':'Археологический слой, свидетельствующий о торговле, не определяет автоматически политический ранг города. Для сравнения Киева и Новгорода нужны княжеское присутствие, церковные учреждения, участие в обмене и отношения с окружающей округой. Эти функции менялись во времени. Процветающий рынок мог сочетаться с зависимостью от другого центра, а высокое династическое значение не гарантировало одинакового богатства во все десятилетия. Современное слово «столица» стоит сопровождать объяснением конкретных полномочий. Так можно увидеть связанное, но многоцентровое пространство Руси и избежать переноса устройства нынешнего государства на раннее Средневековье.',
'02-005':'Летописный сюжет о повторном требовании дани имеет поучительную композицию: нарушение меры приводит к гибели правителя. Это позволяет исследовать представления автора о справедливой власти, но не восстанавливает автоматически точный порядок расчётов с древлянами. Для обсуждения хозяйственных причин нужны сведения о ресурсах общин и способах содержания дружины. Указанная в летописи дата также относится к реконструированной ранней хронологии. Хорошее объяснение сохраняет основу сообщения о конфликте вокруг дани, одновременно обозначая, какие речи, мотивы и подробности казни известны лишь из поздней повествовательной традиции.',
'02-006':'Для датировки крещения Ольги необходимо сопоставлять рассказ о её поездке с византийским описанием придворного приёма. Наличие христианского имени в определённом контексте и участие священника дают важные доводы, но не отвечают одинаково на все вопросы о времени и обстоятельствах обращения. При описании налоговых перемен полезно различать летописные термины, археологически выявленные центры и предполагаемую практику сбора. Уроки и погосты показывают стремление упорядочить отношения власти с населением, однако нельзя по одной формуле восстановить единую подробную инструкцию для всех земель Руси.',
'02-007':'Описание Святослава у византийского автора отражает наблюдения и литературные ожидания его культурной среды. Известная речь или внешность князя должны изучаться вместе с жанром текста и временем записи. Сведения о походах позволяют видеть дальность военных действий, но владение территорией требует иных признаков: постоянного сбора доходов, местных исполнителей и способности удерживать центры. Поэтому разорение противника, установление дани и включение земли в устойчивое управление не следует считать одним событием. Сопоставление договорных условий971года с рассказом о войне помогает отделить военные замыслы от дипломатически закреплённого результата.',
'02-008':'Монеты, строительные проекты и летописный рассказ о Владимире создают разные представления о княжеской власти. Монета с княжеским знаком свидетельствует о публичном образе правителя, но не позволяет рассчитать богатство всего государства. Церковное строительство показывает поддержку новой религии, однако распространение христианских практик в сельской среде исследуют отдельно. Важно отличать действия самого Владимира, деятельность его окружения и позднейшее почитание князя как святого. Эти пласты не исключают друг друга, но требуют собственных вопросов и датировок. Такой разбор даёт более содержательный портрет, чем перечень личных достоинств или недостатков.',
'02-009':'Выбор веры в летописном рассказе построен как объяснение правильности принятого решения для христианского читателя. Это ценный источник о памяти и религиозном смысле, но не стенограмма сравнительного обсуждения религий при дворе. Для реконструкции политической стороны сопоставляют византийский контекст, брак с Анной и события в Корсуни, учитывая расхождения хронологии. Для исследования христианизации населения важны уже иные свидетельства: храмы, погребения, письменность, церковные правила и следы прежних обрядов. Разделение личного крещения князя, официальной поддержки церкви и длительного изменения практик помогает объяснить, почему988год важен, хотя не означает одномоментного обращения каждого жителя.',
'02-010':'Образ Ярослава как законодателя связан с традицией Русской Правды, но дошедший памятник содержит слои разного времени. Нельзя автоматически приписать одному князю все статьи позднейшей редакции. Династические браки показывают признание княжеского дома среди европейских правителей, однако сами по себе не доказывают мирных отношений со всеми соседями. Для оценки наследования полезно различать предполагаемые намерения Ярослава и действия его сыновей после1054года. Известный результат позднейших усобиц не должен превращаться в доказательство, что каждое раннее решение неизбежно вело к распаду.',
'02-011':'Правовой текст описывает нормативные случаи и порядок взысканий, а не статистику всех преступлений. Большой размер штрафа показывает тяжесть установленной санкции, но без судебных данных не сообщает частоты нарушения. Разные редакции Русской Правды включают нормы различного происхождения, поэтому для каждого вывода нужно назвать используемую версию. Слова «холоп», «закуп» и «смерд» рассматривают по контекстам статей, не переводя их механически современными социальными категориями. Полезно составить схему участников одного правового казуса: кто предъявляет требование, кто отвечает и кому поступает платёж. Она выявляет устройство отношений лучше, чем простое заучивание термина.',
'02-012':'Социальный статус в источнике может определяться свободой передвижения, долговыми обязательствами, обязанностью платить дань или зависимостью от конкретного лица. Эти признаки не всегда совпадали. Поэтому построение единой лестницы от князя до «всех остальных» скрывает разнообразие отношений. Закон и житие также показывают разные стороны: первый закрепляет порядок, второе может осуждать злоупотребление с нравственной точки зрения. Чтобы объяснить положение группы, полезно спрашивать о правах, повинностях и способе изменения статуса. Отдельно следует отметить, где сведения относятся к одному региону или позднейшей редакции памятника, а не ко всей истории Руси.',
'02-013':'Клад показывает предметы, отложенные в определённых обстоятельствах и затем не возвращённые владельцем. Он не является обычным кошельком среднего жителя. Присутствие далёкой монеты говорит о связях, но не обязательно о прямой поездке её последнего владельца к месту чеканки: предмет мог пройти через посредников. Для оценки торгового пути сопоставляют распределение находок, транспортные возможности и письменные свидетельства. При этом сельское производство оставалось основой обеспечения населения. Обилие ярких импортных вещей в музейной витрине не должно создавать впечатление, будто большинство жителей занималось только дальним обменом.',
'04-001':'При сравнении Москвы с соседними центрами нельзя объяснять её успех только удобной картой. Похожее положение на путях сообщения могло сочетаться с разными династическими кризисами, отношениями с Ордой и церковными связями. Проверять преимущество следует по конкретному времени: какие доходы были доступны, как использовались браки и договоры, кто поддерживал князя. Позднейшая победа Москвы не доказывает, что она была неизбежна с самого начала. Разделение исходных ресурсов, решений и непредвиденных событий помогает увидеть процесс, сохраняя место альтернативам без сочинения недоказанной иной истории.',
'04-002':'Духовная грамота князя показывает распределение владений и имущества, а не полный бюджет его правления. Для обсуждения накопления ресурсов полезно сопоставлять завещания, договоры и летописные сообщения о выплатах Орде. Прозвище «Калита» само по себе не объясняет механизм политического успеха и не доказывает каждую легенду о богатстве. Сотрудничество с ханской властью давало возможности, но сопровождалось обязательствами и зависело от её решений. Отдельно исследуют отношения с церковью и другими князьями. Тогда оценка не сводится к выбору между образами безупречного собирателя земель и исключительно корыстного посредника.',
'04-003':'Биография Дмитрия соединяет военное руководство, династическую политику и управление княжеством. Самая известная победа не должна заслонять отношения с соседями и последующее разорение Москвы. Для проверки политического результата сопоставляют военный исход, выплату дани, право на великое княжение и устойчивость наследования. Эти показатели могли изменяться неодинаково. Поздние повествования о Куликовской битве выражают память и религиозное осмысление, поэтому их подробности проверяют по времени создания и независимым свидетельствам. Такой подход позволяет признавать значение князя, сохраняя анализ реальных ограничений его власти.',
'04-004':'Численность средневековых армий особенно трудно восстановить: повествователь мог использовать большое число как знак масштаба и славы. Без независимой базы точная цифра создаёт ложную уверенность. Археологические находки, ландшафт и письменная традиция дополняют друг друга, но отвечают на разные вопросы о месте и ходе боя. Полезно отделять надёжный общий исход от спорной последовательности отдельных эпизодов. При оценке последствий нужно сравнить1380год с событиями1382года: победа над Мамаем и прекращение ордынской зависимости — разные исторические задачи. Память о битве позднее менялась и также стала отдельным предметом исследования.',
'04-005':'Участники усобицы ссылались на разные основания прав: старшинство внутри рода, наследование от отца к сыну и прежние договорённости. Эти основания нельзя представить одним бесспорным правилом, которое все одинаково понимали. Историк сопоставляет договорные и духовные грамоты с летописным изложением, учитывая интересы составителей. Жестокость борьбы не объясняет её причин без исследования ресурсов городов, поддержки знати и внешних связей. Позднейшая победа ВасилияII не означает, что каждое его действие с самого начала выражало общегосударственную программу. Нужно различать заявленные права, способы мобилизации сторонников и итоговые изменения власти.',
'04-006':'Для оценки централизации при ИванеIII полезно проверить несколько отдельных полномочий: кто собирал налоги, назначал наместников, рассматривал тяжбы и вёл внешние переговоры. Их переход к Москве мог идти с разной скоростью. Символика власти и титул свидетельствуют о притязаниях правителя, но реальную административную практику устанавливают по другим документам. Включение новой земли также сопровождалось переговорами, конфискациями и перестройкой местных элит. Поэтому выражение «собирание земель» описывает итог лишь в общем виде. Оно требует объяснения того, чья самостоятельность сокращалась и какие институты связывали расширившееся государство.',
'04-007':'Московский и новгородский рассказ могли по-разному объяснять конфликт: защитой веры, нарушением договора или угрозой местным правам. Эти формулировки одновременно выражали политические интересы сторон. Для реконструкции важно сопоставить военные действия, договорные условия и последующие изменения собственности. Уничтожение вечевого порядка не означало прекращения всей городской жизни или торговли. С другой стороны, сохранение торговли не отменяет потери политической самостоятельности и переселений части населения. Сравнение разных показателей помогает увидеть масштаб преобразований, не сводя их к торжественной формуле объединения или к образу одномоментного исчезновения города.',
'04-008':'Военное противостояние на реке не всегда завершается большим сражением. Для объяснения отхода Ахмата важны снабжение, погода, действия союзников и положение его власти. Летописное описание может подчёркивать религиозный смысл спасения, тогда как дипломатические обстоятельства требуют отдельной реконструкции. Условная граница1480года полезна для обозначения прекращения прежней зависимости Москвы, но отношения с разными ордынскими наследниками продолжались. Не следует превращать одно противостояние в исчезновение всех степных государств или всех форм внешней угрозы. Политическое изменение устанавливается по конкретным обязанностям и полномочиям, а не только по факту отсутствия боя.',
'04-009':'Общее право, внешняя политика и управление на местах не обязательно складывались одновременно. Укрепление центрального суда могло сочетаться с сохранением местных обычаев и особыми условиями службы знати. Документ о назначении наместника показывает формальную компетенцию, но не все способы её использования. Для исследования нужно спрашивать, как жители могли обращаться к власти, какие платежи собирались и кто контролировал исполнителей. Это позволяет увидеть государство как систему отношений, а не только список учреждений. Сравнение соседних земель также помогает отличить общую тенденцию от практики, известной лишь по одному хорошо сохранившемуся архиву.',
'04-010':'Юридическая формула регулирует определённый случай и нуждается в контексте соседних статей. Ограничение крестьянского перехода включает срок и расчёт с владельцем; оно не является полным описанием всей хозяйственной зависимости. Для оценки реальной возможности ухода нужны сведения об имущественном положении семьи и практике взысканий. Точно так же правила о судебных исполнителях помогают понять устройство суда, но не доказывают его одинаковую работу в каждом уезде. Сопоставление нормативного акта с частными документами позволяет различить объявленный порядок, местные способы исполнения и нарушения. Это необходимый шаг между чтением закона и выводом о повседневной жизни.',
'04-011':'Включение Пскова, Смоленска и Рязани происходило в неодинаковых условиях, поэтому полезно сравнить способы изменения власти. Военная кампания, ликвидация местной самостоятельности и династическое решение опирались на разные сочетания принуждения и договорённостей. Общий результат расширения государства не отменяет этих различий. Для оценки устойчивости приобретения нужно проследить административное устройство и отношения с местной знатью после события. Отдельно исследуют, как официальная память представляла действия правителя. Сравнение способов включения помогает объяснить, почему единое государство сохраняло разнообразные местные практики даже после прекращения независимости прежних политических центров.'}
for id,t in extra.items():
 p=Path(f'src/content/lessons/{id}.json');d=json.loads(p.read_text());before=d['deep']['text']
 if t not in before:d['deep']['text']+='\n\n'+t
 assert d['deep']['text'].startswith(before)
 p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n');print(id,len(d['deep']['text'].split()))
